insert into public.companies (id, name, line, unit, form, match, source_label, source_url) values ('tesla', 'Tesla', 'Electric cars, the software that drives them, and batteries for homes and the grid.', 'one electric car', 'car', array['tesla','elon musk','musk']::text[], 'Tesla investor relations, ir.tesla.com', 'https://ir.tesla.com') on conflict (id) do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('tesla', 'drive', 0, 'Motors & wheels', null, array['motor','motors','drive unit']::text[], 'The muscle. An electric motor on each axle turns the wheels, with almost no moving parts.', 'Tesla designs its own electric motors and drive units; dual-motor cars carry one on each axle.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('tesla', 'battery', 1, 'Battery pack', null, array['battery','batteries','4680','cells','energy','megapack','powerwall','powercore','storage','supercharger','charging','charger']::text[], 'The fuel tank. Thousands of cells in the floor store the energy and stiffen the car.', 'The pack sits in the floor as part of the car’s structure. Tesla also builds its own 4680 cells, and sells the same battery know-how as Powerwall and Megapack.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('tesla', 'computer', 2, 'Self-driving computer', null, array['fsd','autopilot','self-driving','autonomy','robotaxi','ai5','ai4','computer','super intelligence','software','update']::text[], 'The brain. It reads the cameras many times a second and decides how to steer and brake.', 'Every new Tesla has an onboard AI computer that runs Full Self-Driving (Supervised) from camera video.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('tesla', 'body', 3, 'Body', null, array['cybercab','model y','model 3','cybertruck','model s','model x','semi','deliveries','vehicle','vehicles','car','cars']::text[], 'The shell. Big sections are cast in one piece instead of welded from dozens.', 'Tesla casts large parts of the body in single pieces, a method it calls Gigacasting, to build cars with fewer parts.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('tesla', 'glass', 4, 'Cameras & glass', null, array['camera','cameras','vision']::text[], 'The eyes. Eight cameras around the car see the road; there is no radar or lidar.', 'Tesla’s driver assistance uses cameras only, which Tesla calls Tesla Vision.') on conflict do nothing;
insert into public.companies (id, name, line, unit, form, match, source_label, source_url) values ('nvidia', 'Nvidia', 'Chips and software that train and run most of the world’s AI.', 'one data-centre GPU', 'gpu', array['nvidia','jensen huang']::text[], 'NVIDIA Blackwell architecture, nvidia.com', 'https://www.nvidia.com/en-us/data-center/technologies/blackwell-architecture/') on conflict (id) do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('nvidia', 'board', 0, 'Board & power', null, array['server','rack','nvl72','dgx']::text[], 'The base. Power stages feed the chip, and the edge connector plugs it into the server.', 'The GPU module carries the chip package, its power delivery and the connectors that link it to the server and to other GPUs.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('nvidia', 'substrate', 1, 'Package', null, array['packaging','cowos','tsmc']::text[], 'The adapter. It fans the chip’s thousands of tiny contacts out to the board.', 'The dies and memory sit on one package, which connects them to each other and to the board underneath.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('nvidia', 'memory', 2, 'HBM memory', null, array['hbm','memory']::text[], 'Memory stacked like towers right beside the chip, so data has a short trip.', 'Blackwell GPUs use HBM3e, high-bandwidth memory stacked in layers next to the compute dies.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('nvidia', 'die', 3, 'GPU dies', null, array['blackwell','rubin','gpu','gpus','chip','chips']::text[], 'The engine. Two dies joined into one GPU do the maths that trains and runs AI.', 'Blackwell packs 208 billion transistors into two dies, joined by a 10 TB/s chip-to-chip link so they work as one GPU.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('nvidia', 'lid', 4, 'Heat spreader', null, array[]::text[], 'The lid. It protects the dies and spreads their heat evenly.', 'A metal lid sits on top of the package and passes the heat from the dies to the cooler.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('nvidia', 'cooling', 5, 'Cooling', null, array['cooling','liquid','power']::text[], 'The radiator. Fins, or liquid cold plates in the newest racks, carry the heat away.', 'Top Blackwell systems such as GB200 NVL72 are liquid-cooled racks.') on conflict do nothing;
insert into public.companies (id, name, line, unit, form, match, source_label, source_url) values ('apple', 'Apple', 'iPhone, Mac, iPad and Watch, plus the services that run on them.', 'one iPhone', 'phone', array['apple','iphone','tim cook']::text[], 'Apple, apple.com/iphone', 'https://www.apple.com/iphone/') on conflict (id) do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('apple', 'back', 0, 'Back glass & MagSafe', null, array['magsafe','wireless charging']::text[], 'The back. A ring of magnets behind the glass snaps chargers and cases into place.', 'A magnet ring behind the back glass lines up MagSafe chargers and accessories.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('apple', 'cameras', 1, 'Cameras', null, array['camera','cameras','photo','photos','video']::text[], 'The eyes. Several lenses, each for a different distance.', 'Pro iPhones carry three rear cameras: main, ultra wide and telephoto.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('apple', 'battery', 2, 'Battery', null, array['battery','battery life']::text[], 'The fuel tank. It fills most of the space inside.', 'The battery takes up most of the phone’s inside; the board and cameras are packed around it.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('apple', 'chip', 3, 'Apple silicon', null, array['chip','chips','silicon','processor','neural','apple intelligence','siri','ai']::text[], 'The brain. A chip Apple designs itself, with a part made for AI.', 'iPhone, iPad and Mac run on chips Apple designs itself; each has a Neural Engine for on-device AI such as Apple Intelligence.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('apple', 'frame', 4, 'Frame', null, array['titanium','aluminum','aluminium','design','fold','foldable','iphone air']::text[], 'The skeleton. A metal rim holds every part in place.', 'The metal frame holds the phone together; recent models have used titanium and aluminium.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('apple', 'display', 5, 'Display & services', null, array['display','screen','ios','app store','icloud','apple music','apple tv','services','apple pay']::text[], 'The window. iOS and Apple’s paid services live on this screen.', 'The screen is where iOS, the App Store, iCloud and Apple Music meet the user. Services are Apple’s second-biggest business after iPhone.') on conflict do nothing;
insert into public.companies (id, name, line, unit, form, match, source_label, source_url) values ('microsoft', 'Microsoft', 'Software and cloud for work, plus Windows, GitHub and Xbox.', 'a customer’s work', 'machine', array['microsoft','satya nadella']::text[], 'Microsoft Investor Relations, microsoft.com', 'https://www.microsoft.com/en-us/investor') on conflict (id) do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('microsoft', 'azure', 0, 'Azure', 'cluster', array['azure','cloud','data center','data centers','datacenter']::text[], 'The power plant. Rows of servers rent out computing to other companies.', 'Azure is Microsoft’s cloud: computing, storage and AI models that other companies rent.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('microsoft', 'copilot', 1, 'Copilot', 'scanner', array['copilot','mai','copilotforce']::text[], 'The assistant arch. Work passes under it and comes out drafted, summed up or fixed.', 'Copilot is Microsoft’s AI assistant, built into Windows, Microsoft 365, GitHub and Edge.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('microsoft', 'm365', 2, 'Microsoft 365', 'rack', array['microsoft 365','office','teams','outlook','excel','word']::text[], 'The office shelves. Documents, mail and meetings, stored and shared.', 'Microsoft 365 bundles Word, Excel, Outlook, Teams and cloud storage for people and businesses.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('microsoft', 'github', 3, 'GitHub', 'gate', array['github','codespaces']::text[], 'The code gate. Software from millions of developers is checked in here.', 'GitHub hosts code for developers and companies, with Copilot for writing code.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('microsoft', 'windows', 4, 'Windows & devices', 'devices', array['windows','surface','pc','pcs']::text[], 'The desks. Windows runs on the PCs people use every day.', 'Windows is the operating system on most of the world’s PCs; Surface is Microsoft’s own hardware.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('microsoft', 'xbox', 5, 'Xbox & games', 'dock', array['xbox','game','games','gaming','activision']::text[], 'The shipping dock. Games go out to consoles, PCs and phones.', 'Xbox covers Microsoft’s consoles, Game Pass and studios including Activision Blizzard.') on conflict do nothing;
insert into public.companies (id, name, line, unit, form, match, source_label, source_url) values ('google', 'Google', 'Search, YouTube, Android and Gemini, paid for mostly by ads, plus a cloud business.', 'a question someone types', 'machine', array['google','alphabet','deepmind','sundar pichai']::text[], 'Alphabet Investor Relations, abc.xyz', 'https://abc.xyz/investor/') on conflict (id) do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('google', 'search', 0, 'Search & ads', 'scanner', array['search','ads','advertising','chrome']::text[], 'The reader. Every question is matched with answers, and with ads that pay for it.', 'Google Search answers billions of questions a day; ads next to the results earn most of Alphabet’s revenue.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('google', 'gemini', 1, 'Gemini', 'rack', array['gemini','bard','ai mode','tasks agent','agent']::text[], 'The model shelf. One family of AI models serves every Google product.', 'Gemini is Google’s family of AI models, used in the Gemini app, Search, Workspace and Cloud.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('google', 'youtube', 2, 'YouTube', 'dock', array['youtube','shorts']::text[], 'The broadcast dock. Videos go out to viewers everywhere.', 'YouTube is Google’s video platform, paid for by ads and subscriptions.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('google', 'cloud', 3, 'Cloud & TPUs', 'cluster', array['cloud','tpu','tpus','data center','data centers']::text[], 'The power plant. Google rents out its servers and its own AI chips, TPUs.', 'Google Cloud sells computing, data tools and AI, running on Google’s own TPU chips as well as GPUs.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('google', 'android', 4, 'Android & Pixel', 'devices', array['android','pixel','play store']::text[], 'The phones. Android runs on most of the world’s smartphones.', 'Android is Google’s mobile operating system; Pixel is its own line of phones.') on conflict do nothing;
insert into public.companies (id, name, line, unit, form, match, source_label, source_url) values ('openai', 'OpenAI', 'AI models, sold through ChatGPT and to developers.', 'a prompt', 'machine', array['openai','chatgpt','sam altman']::text[], 'OpenAI, openai.com', 'https://openai.com/') on conflict (id) do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('openai', 'chatgpt', 0, 'ChatGPT', 'scanner', array['chatgpt','gpt','agent','agents']::text[], 'The front desk. People type, and the model answers.', 'ChatGPT is OpenAI’s assistant app, with free and paid plans for people and businesses.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('openai', 'api', 1, 'API', 'gate', array['api','developers','platform']::text[], 'The side door. Other companies plug OpenAI’s models into their own products.', 'The OpenAI API lets developers build OpenAI’s models into their apps and pay per use.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('openai', 'codex', 2, 'Codex', 'rack', array['codex','coding','code']::text[], 'The workshop. An agent that writes and fixes code.', 'Codex is OpenAI’s coding agent for developers.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('openai', 'sora', 3, 'Sora', 'dock', array['sora','video','image','images']::text[], 'The film dock. Prompts go in, video comes out.', 'Sora is OpenAI’s video model and app.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('openai', 'compute', 4, 'Compute', 'cluster', array['stargate','compute','data center','data centers','chips']::text[], 'The power plant. Huge data centres train and run the models.', 'OpenAI is building data centres with partners under the Stargate name.') on conflict do nothing;
insert into public.companies (id, name, line, unit, form, match, source_label, source_url) values ('anthropic', 'Anthropic', 'The Claude family of AI models, for people, businesses and developers.', 'a request', 'machine', array['anthropic','claude']::text[], 'Anthropic, anthropic.com', 'https://www.anthropic.com/') on conflict (id) do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('anthropic', 'claude', 0, 'Claude apps', 'scanner', array['claude']::text[], 'The front desk. People and teams ask Claude for help.', 'Claude is Anthropic’s assistant, on the web, desktop and phone, with plans for people and teams.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('anthropic', 'api', 1, 'Developer platform', 'gate', array['api','developers','platform','bedrock','vertex']::text[], 'The side door. Companies build Claude into their own products.', 'Developers use Claude through Anthropic’s API and through cloud platforms like Amazon Bedrock and Google Cloud Vertex AI.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('anthropic', 'code', 2, 'Claude Code', 'rack', array['claude code','coding','code','agent','agents']::text[], 'The workshop. An agent that writes and changes code with a developer.', 'Claude Code is Anthropic’s coding agent, used in the terminal, in code editors and on the web.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('anthropic', 'compute', 3, 'Compute', 'cluster', array['compute','tpu','tpus','trainium','data center','data centers']::text[], 'The power plant. Data centres train and run the models.', 'Anthropic trains and runs Claude on chips from several providers, including Google TPUs and Amazon Trainium.') on conflict do nothing;
insert into public.companies (id, name, line, unit, form, match, source_label, source_url) values ('meta', 'Meta', 'Facebook, Instagram and WhatsApp, paid for by ads, plus AI and smart glasses.', 'a post', 'machine', array['meta','facebook','instagram','whatsapp','zuckerberg']::text[], 'Meta Investor Relations, investor.atmeta.com', 'https://investor.atmeta.com/') on conflict (id) do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('meta', 'apps', 0, 'Facebook, Instagram, WhatsApp', 'dock', array['facebook','instagram','whatsapp','threads','messenger']::text[], 'The broadcast dock. Posts and messages go out to billions of people.', 'Meta’s apps (Facebook, Instagram, WhatsApp, Messenger and Threads) are used by billions of people every day.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('meta', 'ads', 1, 'Ads', 'scanner', array['ads','advertising']::text[], 'The matcher. Each post slot is matched with an ad, which pays for everything.', 'Almost all of Meta’s revenue comes from ads shown in its apps.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('meta', 'ai', 2, 'Meta AI & Llama', 'rack', array['llama','meta ai','superintelligence']::text[], 'The model shelf. Meta’s own AI models, some released openly.', 'Meta AI is the assistant inside Meta’s apps; Llama is Meta’s family of openly released models.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('meta', 'glasses', 3, 'Glasses & Quest', 'devices', array['quest','glasses','ray-ban','vr','reality labs']::text[], 'The wearables. Smart glasses and headsets.', 'Reality Labs makes Ray-Ban Meta glasses and Quest headsets.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('meta', 'compute', 4, 'Data centres', 'cluster', array['data center','data centers','compute']::text[], 'The power plant. Huge data centres train the models and rank the feeds.', 'Meta is spending heavily on new data centres for AI.') on conflict do nothing;
insert into public.companies (id, name, line, unit, form, match, source_label, source_url) values ('jfrog', 'JFrog', 'Software that stores, checks and ships the files other software is built from.', 'a software package', 'machine', array['jfrog']::text[], 'JFrog Platform overview, docs.jfrog.com', 'https://docs.jfrog.com/setup/docs/get-started/jfrog-platform-overview') on conflict (id) do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('jfrog', 'curation', 0, 'Curation', 'gate', array['curation']::text[], 'The gate at the door. Risky packages from the internet are turned away before they come in.', 'Works at the moment a team downloads an open-source package, and keeps risky dependencies out of its repositories before they are used.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('jfrog', 'artifactory', 1, 'Artifactory', 'rack', array['artifactory']::text[], 'The warehouse. Every file a team builds is stored on a shelf, labelled with its version.', 'Automates and manages binaries and artifacts from build to release. It is the source of truth the other parts read from.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('jfrog', 'xray', 2, 'Xray & Advanced Security', 'scanner', array['xray','security']::text[], 'The scanner arch. Each package passes under it and is checked for known security holes and licence problems.', 'Xray finds open-source vulnerabilities and licence violations before production. Advanced Security also scans source code and binaries with JFrog’s own engines.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('jfrog', 'distribution', 3, 'Distribution', 'dock', array['distribution']::text[], 'The loading dock. Finished releases are sealed into a bundle and sent out on several rails at once.', 'Distributes immutable release bundles and automates delivery of software updates.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('jfrog', 'runtime', 4, 'Runtime', 'cluster', array['runtime','kubernetes']::text[], 'The running floor. Software that is live in Kubernetes is watched, with a gauge per cluster.', 'Gives security and operational insight into Kubernetes environments, with Artifactory kept as the source of truth.') on conflict do nothing;
insert into public.company_parts (company_id, id, position, name, kind, match, role, what) values ('jfrog', 'connect', 5, 'Connect', 'devices', array['iot','connect']::text[], 'The antenna rack. Updates go out to fleets of devices in the field.', 'Secures the development lifecycle of connected (IoT) devices, from managing files to deploying updates across fleets.') on conflict do nothing;
